<template>
  <div class="operations-pane" v-loading="loading">
    <header class="pane-head"><div><span>KAOPU OPERATIONS</span><h2>运营与信任总览</h2><p>用固定窗口观察四条真实业务链路，集中处理积压；学生商品款不计入平台收入。</p></div><div><el-select v-model="days" style="width:120px" @change="load"><el-option label="近 7 天" :value="7" /><el-option label="近 30 天" :value="30" /><el-option label="近 90 天" :value="90" /></el-select><el-button @click="load">刷新</el-button></div></header>

    <section class="headline-grid"><article><span>全部待办</span><b>{{ dashboard?.headline.pendingTotal || 0 }}</b><small>需要运营人员处理</small></article><article :class="{ danger: dashboard?.headline.overdueTotal }"><span>超过处理时限</span><b>{{ dashboard?.headline.overdueTotal || 0 }}</b><small>举报、申诉及内容治理待办</small></article><article :class="{ danger: Number(dashboard?.headline.promotionNetContribution || 0) < 0 }"><span>推广净贡献</span><b>¥{{ dashboard?.headline.promotionNetContribution || '0.00' }}</b><small>毛额 ¥{{ dashboard?.headline.promotionRevenue || '0.00' }} · 人工 ¥{{ dashboard?.headline.promotionManualCost || '0.00' }}</small></article><article><span>平均人工核验</span><b>{{ dashboard?.headline.averageManualReviewMinutes || 0 }} 分</b><small>申请到管理员确认</small></article><article :class="{ danger: dashboard?.headline.promotionComplaintRate }"><span>推广投诉率</span><b>{{ dashboard?.headline.promotionComplaintRate || 0 }}%</b><small>{{ dashboard?.headline.promotionComplaintCount || 0 }} 条人工投诉留痕</small></article><article><span>推广点击率</span><b>{{ dashboard?.headline.promotionCtr || 0 }}%</b><small>去重点击 / 去重曝光</small></article></section>

    <section class="section-block v1-block">
      <header><div><h3>V1 产品健康度</h3><p>只统计登录用户的日级产品入口聚合，不保存 IP、搜索词或访问内容。</p></div><el-tag :type="dashboard?.readiness.ready ? 'success' : 'warning'">{{ dashboard?.readiness.ready ? '业务条件就绪' : '仍有上线阻塞项' }}</el-tag></header>
      <div class="v1-kpis"><article><span>校园认证用户</span><b>{{ dashboard?.headline.verifiedCampusUsers || 0 }}</b></article><article><span>DAU</span><b>{{ dashboard?.product.dau || 0 }}</b></article><article><span>WAU</span><b>{{ dashboard?.product.wau || 0 }}</b></article><article><span>7 日回访率</span><b>{{ dashboard?.product.sevenDayReturnRate || 0 }}%</b></article><article><span>核心入口导流</span><b>{{ dashboard?.product.coreEntryUsers || 0 }}</b></article></div>
      <div class="surface-grid"><article v-for="surface in dashboard?.product.surfaceActiveUsers || []" :key="surface.surface"><b>{{ surfaceLabel(surface.surface) }}</b><span>{{ surface.users }} 人 · {{ surface.visits }} 次</span></article></div>
      <div class="readiness-grid"><article v-for="check in dashboard?.readiness.checks || []" :key="check.key" :class="{ passed: check.passed }"><i>{{ check.passed ? '✓' : '!' }}</i><div><b>{{ check.label }}</b><span>当前 {{ check.current }} · 目标 {{ check.target }}</span></div></article></div>
      <el-alert class="release-note" type="info" :closable="false" :title="dashboard?.readiness.note || ''" />
    </section>

    <section class="section-block"><header><div><h3>四条运营漏斗</h3><p>每列都是所选窗口内的真实记录数；不同阶段不是虚构演示数据。</p></div><time v-if="dashboard">更新于 {{ formatTime(dashboard.generatedAt) }}</time></header><div class="funnel-grid"><article v-for="funnel in dashboard?.funnels || []" :key="funnel.key"><div class="funnel-title"><i>{{ funnelNumber(funnel.key) }}</i><div><h4>{{ funnel.label }}</h4><p>{{ funnel.note }}</p></div></div><ol><li v-for="stage in funnel.stages" :key="stage.label"><div><span>{{ stage.label }}</span><b>{{ stage.value }}</b></div><em><i :style="{ width: stageWidth(funnel.stages, stage.value) }" /></em></li></ol></article></div></section>

    <section class="section-block"><header><div><h3>运营处理队列</h3><p>盈利订单始终由管理员逐单人工核验；不会因到账回调自动启用推广。</p></div></header><div class="queue-grid"><router-link v-for="queue in dashboard?.queues || []" :key="queue.key" :to="queue.route"><span>{{ queue.label }}</span><b>{{ queue.count }}</b><small v-if="queue.overdue">其中 {{ queue.overdue }} 条已超过 24 小时</small><small v-else>当前无超时积压</small><em>前往处理 →</em></router-link></div></section>

    <section class="section-block audit-block"><header><div><h3>统一审计时间线</h3><p>串联管理员动作、举报、信用处理和申诉，便于复核原因、操作者和时间。</p></div><router-link to="/admin?tab=market">查看市集管理日志</router-link></header><div v-if="dashboard?.timeline.length" class="timeline"><article v-for="entry in dashboard.timeline" :key="entry.id"><i :class="entry.kind">{{ kindLabel(entry.kind) }}</i><div><strong>{{ entry.title }}</strong><p>{{ entry.actor }} · {{ entry.target }}</p></div><el-tag size="small" :type="statusType(entry.status)">{{ statusLabel(entry.status) }}</el-tag><time>{{ formatTime(entry.createdAt) }}</time></article></div><el-empty v-else description="暂无运营审计记录" /></section>
  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from "vue";
import { ElMessage } from "element-plus";
import { marketApi, type MarketOperationsDashboard } from "@/api/market";

const loading = ref(false);
const days = ref(30);
const dashboard = ref<MarketOperationsDashboard | null>(null);

onMounted(load);

async function load() {
  loading.value = true;
  try { dashboard.value = await marketApi.adminOperations(days.value, { suppressErrorMessage: true }); }
  catch (error) { ElMessage.error(error instanceof Error ? error.message : "运营数据加载失败"); }
  finally { loading.value = false; }
}

function stageWidth(stages: Array<{ value: number }>, value: number) { const max = Math.max(1, ...stages.map((stage) => stage.value)); return `${Math.max(value ? 8 : 0, Math.round((value / max) * 100))}%`; }
function funnelNumber(key: string) { return ({ trade: "01", wanted: "02", learning: "03", promotion: "04" } as Record<string, string>)[key] || "·"; }
function surfaceLabel(value: string) { return ({ schedule: "个性化课表", portal: "校园门户", square: "校园广场", market: "实体市集", learning: "学习资料" } as Record<string, string>)[value] || value; }
function kindLabel(kind: string) { return ({ action: "操作", report: "举报", appeal: "申诉", violation: "信用" } as Record<string, string>)[kind] || kind; }
function statusLabel(status: string) { return ({ recorded: "已记录", pending: "待处理", resolved: "已处理", rejected: "未通过", approved: "已通过", active: "生效中", revoked: "已撤销", expired: "已过期" } as Record<string, string>)[status] || status; }
function statusType(status: string) { return status === "pending" ? "warning" : ["rejected", "active"].includes(status) ? "danger" : ["resolved", "approved", "recorded"].includes(status) ? "success" : "info"; }
function formatTime(value: string) { return new Date(value).toLocaleString("zh-CN", { month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit" }); }
</script>

