x;align-items:center;justify-content:space-between;font-size:9px}.funnel-grid li b{font-size:12px}.funnel-grid li em{display:block;height:5px;margin-top:4px;overflow:hidden;border-radius:3px;background:var(--cpu-surface-soft)}.funnel-grid li em i{display:block;height:100%;border-radius:3px;background:var(--cpu-primary)}.queue-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.queue-grid a{display:grid;grid-template-columns:1fr auto;gap:3px 10px;padding:13px;border:1px solid var(--cpu-border-soft);border-radius:10px;color:inherit;text-decoration:none}.queue-grid a:hover{border-color:var(--cpu-primary)}.queue-grid span{font-size:11px;font-weight:700}.queue-grid b{grid-row:1/3;grid-column:2;color:var(--cpu-primary);font-size:24px}.queue-grid small{color:var(--cpu-text-secondary);font-size:9px}.queue-grid em{grid-column:1/-1;margin-top:5px;color:var(--cpu-primary);font-size:9px;font-style:normal}.timeline{display:flex;flex-direction:column}.timeline article{display:grid;grid-template-columns:42px minmax(0,1fr) auto 100px;align-items:center;gap:10px;padding:10px 0;border-top:1px solid var(--cpu-border-soft)}.timeline article>i{padding:4px;border-radius:6px;color:var(--cpu-primary);background:var(--cpu-primary-soft);font-size:8px;font-style:normal;text-align:center}.timeline article>i.report{color:#b45309;background:#fef3c7}.timeline article>i.violation{color:#b91c1c;background:#fee2e2}.timeline strong{display:block;overflow:hidden;font-size:10px;text-overflow:ellipsis;white-space:nowrap}.timeline p{margin:3px 0 0;color:var(--cpu-text-secondary);font-size:8px}.timeline time{color:var(--cpu-text-secondary);font-size:8px;text-align:right}@media(max-width:1100px){.funnel-grid{grid-template-columns:repeat(2,1fr)}.headline-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:720px){.pane-head{align-items:flex-start;flex-direction:column}.pane-head>div:last-child{width:100%}.pane-head>div:last-child .el-select{flex:1}.queue-grid{grid-template-columns:1fr 1fr}.timeline article{grid-template-columns:38px minmax(0,1fr) auto}.timeline time{display:none}}@media(max-width:520px){.headline-grid,.funnel-grid,.queue-grid{grid-template-columns:1fr}.section-block{padding:14px}.section-block>header{align-items:flex-start;flex-direction:column}.funnel-grid{display:flex;overflow-x:auto;scroll-snap-type:x mandatory}.funnel-grid>article{min-width:82%;scroll-snap-align:start}}
